    24→constexpr auto conditional_reverse(arithmetic auto value, std::endian from, std::endian to) {
    25→	using type = decltype(value);
    26→
    27→	if(from != to) {
    28→		if constexpr(std::is_same_v<type, float>) {
    29→			value = std::bit_cast<type>(std::byteswap(std::bit_cast<std::uint32_t>(value)));
    30→		} else if constexpr(std::is_same_v<type, double>) {
    31→			value = std::bit_cast<type>(std::byteswap(std::bit_cast<std::uint64_t>(value)));
    32→		} else {
    33→			value = std::byteswap(value);
    34→		}
    35→	}
    36→
    37→	return value;
    38→}
    39→
    40→template<std::endian from, std::endian to>
    41→constexpr auto conditional_reverse(arithmetic auto value) {
    42→	using type = decltype(value);
    43→
    44→	if constexpr(from != to) {
    45→		if constexpr(std::is_same_v<type, float>) {
