   330→	auto storage() const {
   331→		return buffer_.data();
   332→	}
   333→
   334→	/**
   335→	 * @return Pointer to the underlying storage.
   336→	 */
   337→	auto storage() {
   338→		return buffer_.data();
   339→	}
   340→
   341→	/**
   342→	 * @brief Advances the write cursor.
   343→	 * 
   344→	 * @param size The number of bytes by which to advance the write cursor.
   345→	 */
   346→	void advance_write(size_type bytes) {
   347→		assert(buffer_.size() >= (write_ + bytes));
   348→		write_ += bytes;
   349→	}
   350→
   351→	/**
   352→	 * @brief The amount of space left in the container.
   353→	 * 
   354→	 * @return The number of free bytes.
   355→	 */
   356→	auto free() const {
   357→		return buffer_.size() - write_;
   358→	}
   359→	
   360→	/*
   361→	 * @brief Resets both the read and write cursors back to the beginning
   362→	 * of the buffer.
   363→	 * 
   364→	 * @note The underlying buffer will not be cleared but should be treated
   365→	 * as thought it has been.
   366→	 */
   367→	void clear() {
   368→		read_ = write_ = 0;
   369→	}
   370→};
