     8→struct UserPacket {
     9→	uint64_t user_id;
    10→	std::string username;
    11→	int64_t timestamp;
    12→	uint8_t has_optional_field;
    13→	uint32_t optional_field;
    14→
    15→	/**
    16→	 * If serialisation and deserialisation logic differs, we can also
    17→	 * define operator<< and operator>> for use with stream << type
    18→	 * and stream >> type
    19→	 */
    20→	void serialise(auto& stream) {
    21→		stream(user_id, username, timestamp, has_optional_field);
    22→
    23→		if (has_optional_field) {
    24→			stream(optional_field);
    25→			
    26→			// can also use this syntax:
    27→			// stream & optional_field;
    28→		}
    29→	}
    30→
    31→	bool operator==(const UserPacket& rhs) const {
    32→		return user_id == rhs.user_id
    33→			&& username == rhs.username
    34→			&& timestamp == rhs.timestamp
    35→			&& has_optional_field == rhs.has_optional_field
    36→			&& optional_field == rhs.optional_field;
    37→	}
    38→};
    39→
    40→int main() {
    41→	std::vector<char> buffer;
    42→	hexi::buffer_adaptor adaptor(buffer);
    43→	hexi::binary_stream stream(adaptor);
    44→
    45→	UserPacket packet_in {
    46→		.user_id = 0,
    47→		.username = "Administrator",
    48→		.timestamp = time(NULL),
    49→		.has_optional_field = 1,
    50→		.optional_field = 9001
    51→	};
    52→
    53→	// serialise
    54→	stream.serialise(packet_in);
    55→
    56→	// round-trip deserialise
    57→	UserPacket packet_out{};
    58→	stream.deserialise(packet_out);
    59→
    60→	if(packet_in == packet_out) {
    61→		std::print("Everything went great!");
    62→	} else {
    63→		std::print("Something went wrong!");
    64→	}
    65→}

