   607→	 */
   608→	binary_stream& operator>>(prefixed_varint<std::string_view> adaptor) {
   609→		const auto size = varint_decode<size_type>(*this);
   610→
   611→		// if an error was triggered during decode
   612→		if(state_ != stream_state::ok) {
   613→			return *this;
   614→		}
