    39→
    40→public:
    41→	buffer_adaptor(buf_type& buffer)
    42→		: buffer_(buffer),
    43→		  read_(0),
    44→		  write_(buffer.size()) {}
    45→
    46→	buffer_adaptor(buf_type& buffer, init_empty_t)
    47→		: buffer_(buffer),
    48→		  read_(0),
    49→		  write_(0) {}
    50→
    51→	buffer_adaptor(buffer_adaptor&& rhs) = delete;
    52→	buffer_adaptor& operator=(buffer_adaptor&&) = delete;
    53→	buffer_adaptor& operator=(const buffer_adaptor&) = delete;
