   102→	/**
   103→	 * @brief Copies a number of bytes to the provided buffer but without advancing
   104→	 * the read cursor.
   105→	 * 
   106→	 * @note The destination buffer must not overlap with the underlying buffer
   107→	 * being used by the buffer_adaptor.
   108→	 * 
   109→	 * @param[out] destination The buffer to copy the data to.
   110→	 * @param length The number of bytes to copy.
   111→	 */
   112→	void copy(void* destination, size_type length) const {
   113→		assert(destination && !region_overlap(buffer_.data(), buffer_.size(), destination, length));
   114→		std::memcpy(destination, read_ptr(), length);
   115→	}
   116→
   117→	/**
   118→	 * @brief Skip over a number of bytes.
   119→	 * 
   120→	 * Skips over a number of bytes from the container. This should be used
   121→	 * if the container holds data that you don't care about but don't want
   122→	 * to have to read it to another buffer to access data beyond it.
   123→	 * 
   124→	 * @param length The number of bytes to skip.
   125→	 */
   126→	void skip(size_type length) {
   127→		read_ += length;
