   100→template<typename T, typename U>
   101→concept memcpy_read =
   102→	pod<typename T::value_type> && std::ranges::contiguous_range<T>
   103→		&& !has_shr_override<typename T::value_type, U>
   104→		&& !has_deserialise<typename T::value_type, U>;
   105→
   106→template<typename T, typename U>
   107→concept memcpy_write =
   108→	pod<typename T::value_type> && std::ranges::contiguous_range<T>
