   737→	 * @tparam T The type of the POD object.
   738→	 * @param[out] data The object to hold the result.
   739→	 * 
   740→	 * @note Will not be used for types with user-defined serialisation
   741→	 * functions.
   742→	 * 
   743→	 * @return Reference to the current stream.
   744→	 */
   745→	template<pod T>
   746→	requires (!has_shr_override<T, binary_stream> && !arithmetic<T>)
   747→	binary_stream& operator>>(T& data) {
   748→		SAFE_READ(&data, sizeof(data), *this);
   749→		return *this;
   750→	}
