   752→	/**
   753→	 * @brief Deserialises an iterable container that was previously written
   754→	 * with a fixed-length prefix.
   755→	 * 
   756→	 * @tparam T The iterable container type.
   757→	 * @param[out] adaptor The container to hold the result.
   758→	 *
   759→	 * @return Reference to the current stream.
   760→	 */
   761→	template<is_iterable T>
   762→	binary_stream& operator>>(prefixed<T> adaptor) {
   763→		std::uint32_t count = 0;
   764→		*this >> endian::le(count);
   765→		read_container(adaptor.str, count);
   766→		return *this;
   767→	}
