   271→	 * @brief Performs write seeking within the container.
   272→	 * 
   273→	 * @param direction Specify whether to seek in a given direction or to absolute seek.
   274→	 * @param offset The offset relative to the seek direction or the absolute value
   275→	 * when using absolute seeking.
   276→	 */
   277→	void write_seek(const buffer_seek direction, const size_type offset) {
   278→		switch(direction) {
   279→			case buffer_seek::sk_backward:
   280→				write_ -= offset;
   281→				break;
   282→			case buffer_seek::sk_forward:
   283→				write_ += offset;
   284→				break;
   285→			case buffer_seek::sk_absolute:
   286→				write_ = offset;
   287→		}
   288→	}
