   296→
   297→	/**
   298→	 * @return An iterator to the beginning of data available for reading.
   299→	 */
   300→	auto begin() const {
   301→		return buffer_.begin() + read_;
   302→	}
   303→
   304→	/**
   305→	 * @return An iterator to the end of data available for reading.
   306→	 */
   307→	auto end() {
   308→		return buffer_.begin() + write_;
   309→	}
   310→
   311→	/**
