   170→	explicit binary_stream(buf_type& source, exceptions)
   171→		: binary_stream(source, 0) {}
   172→
   173→	explicit binary_stream(buf_type& source, endianness)
   174→		: binary_stream(source, 0) {}
   175→
   176→	explicit binary_stream(buf_type& source, exceptions, endianness)
   177→		: binary_stream(source, 0) {}
   178→
   179→	explicit binary_stream(buf_type& source, size_type read_limit, exceptions)
   180→		: binary_stream(source, read_limit) {}
   181→
   182→	explicit binary_stream(buf_type& source, size_type read_limit, endianness)
   183→		: binary_stream(source, read_limit) {}
   184→
   185→	explicit binary_stream(buf_type& source, size_type read_limit, exceptions, endianness)
   186→		: binary_stream(source, read_limit) {}
   187→
   188→	binary_stream(binary_stream&& rhs) noexcept
   189→		: buffer_(rhs.buffer_), 
   190→		  total_write_(rhs.total_write_),
   191→		  total_read_(rhs.total_read_),
   192→		  state_(rhs.state_),
   193→		  read_limit_(rhs.read_limit_) {
