   195→		rhs.state_ = stream_state::invalid_stream;
   196→	}
   197→
   198→	binary_stream& operator=(binary_stream&&) = delete;
   199→	binary_stream& operator=(binary_stream&) = delete;
   200→	binary_stream(binary_stream&) = delete;
