   270→	/**
   271→	 * @brief Serialises a POD type.
   272→	 * 
   273→	 * @tparam T The type of the POD object.
   274→	 * @param data Reference to the object to be serialised.
   275→	 * 
   276→	 * @note Will not be used for types with user-defined serialisation
   277→	 * functions.
   278→	 * 
   279→	 * @return Reference to the current stream.
   280→	 */
   281→	template<pod T>
   282→	requires (!has_shl_override<T, binary_stream> && !arithmetic<T>)
   283→	binary_stream& operator<<(const T& data) requires writeable<buf_type> {
   284→		write(&data, sizeof(T));
