    28→public:
    29→	explicit buffer_adaptor(buf_type& buffer)
    30→		: buffer_read_adaptor<buf_type>(buffer),
    31→		  buffer_write_adaptor<buf_type>(buffer) {}
    32→
    33→	explicit buffer_adaptor(buf_type& buffer, init_empty_t)
    34→		: buffer_read_adaptor<buf_type>(buffer, init_empty),
    35→		  buffer_write_adaptor<buf_type>(buffer, init_empty) {}
    36→
    37→	/**
    38→	 * @brief Reads a number of bytes to the provided buffer.
    39→	 * 
    40→	 * @param destination The buffer to copy the data to.
    41→	 */
    42→	template<typename T>
    43→	void read(T* destination) {
    44→		buffer_read_adaptor<buf_type>::read(destination);
    45→
    46→		if constexpr(allow_optimise) {
    47→			conditional_clear();
    48→		}
    49→	}
