   230→TEST(binary_stream, no_copy_string_read) {
   231→	std::vector<char> buffer;
   232→	hexi::buffer_adaptor adaptor(buffer);
   233→	hexi::binary_stream stream(adaptor);
   234→	const std::string input { "The quick brown fox jumped over the lazy dog" };
   235→	const std::uint32_t trailing { 0x0DDBA11 };
   236→	stream << hexi::null_terminated(input) << trailing;
   237→
   238→	// check this stream uses a contiguous buffer
   239→	const auto contig = std::is_same_v<decltype(stream)::contiguous_type, hexi::is_contiguous>;
   240→	ASSERT_TRUE(contig);
   241→
   242→	// find the end of the string within the buffer
   243→	const auto stream_buf = stream.buffer();
   244→	const auto pos = stream_buf->find_first_of('\0');
   245→	ASSERT_NE(pos, adaptor.npos);
   246→
   247→	// create a view into the buffer & skip ahead so the next read continues as normal
   248→	std::string_view output(stream_buf->read_ptr(), pos);
   249→	ASSERT_EQ(input, output);
   250→
   251→	// ensure we can still read subsequent data as normal
   252→	stream.skip(pos + 1); // +1 to skip terminator
   253→	std::uint32_t trailing_output = 0;
   254→	stream >> trailing_output;
   255→	ASSERT_EQ(trailing, trailing_output);
   256→}
