   165→public:
   166→	explicit binary_stream(buf_type& source, size_type read_limit = 0)
   167→		: buffer_(source),
   168→		  read_limit_(read_limit) {};
   169→
   170→	explicit binary_stream(buf_type& source, exceptions)
