    25→namespace hexi {
    26→
    27→using namespace detail;
    28→
    29→template<typename buffer_type>
    30→class buffer_sequence;
    31→
    32→template<decltype(auto) block_sz>
    33→concept int_gt_zero = std::integral<decltype(block_sz)> && block_sz > 0;
    34→
    35→template<decltype(auto) block_sz,
    36→	byte_type storage_value_type = std::byte,
    37→	typename allocator = default_allocator<detail::intrusive_storage<block_sz, storage_value_type>>
    38→>
    39→requires int_gt_zero<block_sz>
    40→class dynamic_buffer final : public pmc::buffer {
    41→public:
    42→	using storage_type = intrusive_storage<block_sz, storage_value_type>;
    43→	using value_type   = storage_value_type;
    44→	using node_type    = intrusive_node;
    45→	using size_type    = std::size_t;
    46→	using offset_type  = std::size_t;
    47→	using contiguous   = is_non_contiguous;
    48→	using seeking      = supported;
    49→
    50→	static constexpr auto npos { static_cast<size_type>(-1) };
    51→
    52→	using unique_storage = std::unique_ptr<storage_type, std::function<void(storage_type*)>>;
    53→
    54→private:
    55→	intrusive_node root_;
    56→	size_type size_;
    57→	[[no_unique_address]] allocator allocator_;
    58→
    59→	void link_tail_node(intrusive_node* node) {
    60→		node->next = &root_;
    61→		node->prev = root_.prev;
    62→		root_.prev = root_.prev->next = node;
    63→	}
    64→
    65→	void unlink_node(intrusive_node* node) {
    66→		node->next->prev = node->prev;
    67→		node->prev->next = node->next;
    68→	}
    69→
    70→	inline storage_type* buffer_from_node(const intrusive_node* node) const {
    71→		return reinterpret_cast<storage_type*>(std::uintptr_t(node)
    72→			- offsetof(storage_type, node));
    73→	}
    74→
    75→	void move(dynamic_buffer& rhs) noexcept {
    76→		if(this == &rhs) { // self-assignment
    77→			return;
    78→		}
    79→
    80→		clear(); // clear our current blocks rather than swapping them
    81→
    82→		size_ = rhs.size_;
    83→		root_ = rhs.root_;
    84→		root_.next->prev = &root_;
    85→		root_.prev->next = &root_;
    86→		rhs.size_ = 0;
    87→		rhs.root_.next = &rhs.root_;
    88→		rhs.root_.prev = &rhs.root_;
    89→	}
    90→
    91→	void copy(const dynamic_buffer& rhs) {
    92→		if(this == &rhs) { // self-assignment
    93→			return;
    94→		}
    95→
    96→		const intrusive_node* head = rhs.root_.next;
    97→		root_.next = &root_;
    98→		root_.prev = &root_;
    99→		size_ = 0;
   100→
   101→		while(head != &rhs.root_) {
   102→			auto buffer = allocate();
   103→			*buffer = *buffer_from_node(head);
   104→			link_tail_node(&buffer->node);
   105→			size_ += buffer->write_offset;
   106→			head = head->next;
   107→		}
   108→	}
   109→	
   110→#ifdef HEXI_BUFFER_DEBUG
   111→	void offset_buffers(std::vector<storage_type*>& buffers, size_type offset) {
   112→		std::erase_if(buffers, [&](auto block) {
   113→			if(block->size() > offset) {
   114→				block->read_offset += offset;
   115→				block->write_offset -= offset;
   116→				return false;
   117→			} else {
   118→				return true;
   119→			}
   120→		});
   121→	}
   122→#endif
   123→
   124→	value_type& byte_at_index(const size_type index) const {
   125→		assert(index < size_ && "buffer subscript index out of range");
   126→
   127→		auto head = root_.next;
   128→		auto buffer = buffer_from_node(head);
   129→		const auto offset_index = index + buffer->read_offset;
   130→		const auto node_index = offset_index / block_sz;
   131→
   132→		for(size_type i = 0; i < node_index; ++i) {
   133→			head = head->next;
   134→		}
   135→
   136→		buffer = buffer_from_node(head);
   137→		return (*buffer)[offset_index % block_sz];
   138→	}
   139→
   140→	size_type abs_seek_offset(size_type offset) {
   141→		if(offset < size_) {
   142→			return size_ - offset;
   143→		} else if(offset > size_) {
   144→			return offset - size_;
   145→		} else {
   146→			return 0;
   147→		}
   148→	}
   149→
   150→	[[nodiscard]] storage_type* allocate() {
   151→		return allocator_.allocate();
   152→	}
   153→
   154→	void deallocate(storage_type* buffer) {
   155→		allocator_.deallocate(buffer);
   156→	}
   157→
   158→public:
   159→	dynamic_buffer()
   160→		: root_{ .next = &root_, .prev = &root_ },
   161→		  size_(0) {}
   162→
   163→	~dynamic_buffer() {
   164→		clear();
   165→	}
   166→
   167→	dynamic_buffer& operator=(dynamic_buffer&& rhs) noexcept {
   168→		move(rhs);
   169→		return *this;
   170→	}
   171→
   172→	dynamic_buffer(dynamic_buffer&& rhs) noexcept {
   173→		move(rhs);
   174→	}
   175→
   176→	dynamic_buffer(const dynamic_buffer& rhs) {
   177→		copy(rhs);
   178→	}
   179→
   180→	dynamic_buffer& operator=(const dynamic_buffer& rhs) {
   181→		clear();
   182→		copy(rhs);
   183→		return *this;
   184→	}
   185→
   186→	/**
   187→	 * @brief Reads a number of bytes to the provided buffer.
   188→	 * 
   189→	 * @note The destination buffer must not overlap with any of the underlying
   190→	 * buffers being used by the dynamic buffer.
   191→	 * 
   192→	 * @param[out] destination The buffer to copy the data to.
   193→	 */
   194→	template<typename T>
   195→	void read(T* destination) {
   196→		read(destination, sizeof(T));
   197→	}
   198→
   199→	/**
   200→	 * @brief Reads a number of bytes to the provided buffer.
   201→	 * 
   202→	 * @note The destination buffer must not overlap with any of the underlying
   203→	 * buffers being used by the dynamic buffer.
   204→	 * 
   205→	 * @param[out] destination The buffer to copy the data to.
   206→	 * @param length The number of bytes to read into the buffer.
   207→	 */
   208→	void read(void* destination, size_type length) override {
   209→		assert(length <= size_ && "Chained buffer read too large!");
   210→		size_type remaining = length;
   211→
   212→		while(true) {
   213→			auto buffer = buffer_from_node(root_.next);
   214→			remaining -= buffer->read(
   215→				static_cast<value_type*>(destination) + length - remaining, remaining,
   216→				                         root_.next == root_.prev
   217→			);
   218→
   219→			if(remaining) [[unlikely]] {
   220→				unlink_node(root_.next);
   221→				deallocate(buffer);
   222→			} else {
   223→				break;
   224→			}
   225→		}
   226→
   227→		size_ -= length;
   228→	}
   229→
   230→	/**
   231→	 * @brief Copies a number of bytes to the provided buffer but without advancing
   232→	 * the container's read cursor.
   233→	 * 
   234→	 * @note The source buffer must not overlap with any of the underlying
   235→	 * buffers being used by the dynamic buffer.
   236→	 * 
   237→	 * @param[out] destination The buffer to copy the data to.
   238→	 */
   239→	template<typename T>
   240→	void copy(T* destination) const {
   241→		copy(destination, sizeof(T));
   242→	}
   243→
   244→	/**
   245→	 * @brief Copies a number of bytes to the provided buffer but without advancing
   246→	 * the container's read cursor.
   247→	 * 
   248→	 * @note The destination buffer must not overlap with any of the underlying
   249→	 * buffers being used by the dynamic buffer.
   250→	 * 
   251→	 * @param[out] destination The buffer to copy the data to.
   252→	 * @param length The number of bytes to copy.
   253→	 */
   254→	void copy(void* destination, const size_type length) const override {
   255→		assert(length <= size_ && "Chained buffer copy too large!");
   256→		size_type remaining = length;
   257→		auto head = root_.next;
   258→
   259→		while(true) {
   260→			const auto buffer = buffer_from_node(head);
   261→			remaining -= buffer->copy(
   262→				static_cast<value_type*>(destination) + length - remaining, remaining
   263→			);
   264→
   265→			if(remaining) [[unlikely]] {
   266→				head = head->next;
   267→			} else {
   268→				break;
   269→			}
   270→		}
   271→	}
   272→
   273→#ifdef HEXI_BUFFER_DEBUG
   274→	/**
   275→	 * @brief Retrives underlying buffers owned by the dynamic buffer.
   276→	 *
   277→	 * @param length Limit returned buffers to those holding up to the requested amount
   278→	 * of data.
   279→	 * @param offset The offset to start at.
   280→	 * 
   281→	 * @return Container of pointers to the underlying buffers holding the range of data
   282→	 * requested by length and offset.
   283→	 */
   284→	std::vector<storage_type*> fetch_buffers(const size_type length, const size_type offset = 0) {
   285→		size_type total = length + offset;
   286→		assert(total <= size_ && "Chained buffer fetch too large!");
   287→		std::vector<storage_type*> buffers;
   288→		auto head = root_.next;
   289→
   290→		while(total) {
   291→			auto buffer = buffer_from_node(head);
   292→			size_type read_size = block_sz - buffer->read_offset;
   293→			
   294→			// guard against overflow - buffer may have more content than requested
   295→			if(read_size > total) {
   296→				read_size = total;
   297→			}
   298→
   299→			buffers.emplace_back(buffer);
   300→			total -= read_size;
   301→			head = head->next;
   302→		}
   303→
   304→		if(offset) {
   305→			offset_buffers(buffers, offset);
   306→		}
   307→
   308→		return buffers;
   309→	}
   310→#endif
